import{_ as i,o as e,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2018-Apr-05 -- Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-Apr-05 -- Ceph Performance Weekly","date":"2018-04-06T00:00:00.000Z","updated":"2018-04-07T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","PG 日志","内存管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-Apr-05_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-Apr-05_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),r={name:"posts/2018/2018-Apr-05_-_-_Ceph_Performance_Weekly.md"};function s(p,l,n,a,_,g){return e(),t("div",null,[...l[0]||(l[0]=[o("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Sage, Josh, Adam, Lisa, Alex, Stanley, Nate 等</p><p><strong>会议内容</strong>：</p><p><strong>一、新功能与改进</strong></p><ol><li><p><strong>新Pull Request</strong>：</p><ul><li>Sage提到一个关于加密的新Pull Request。</li><li>Neha提交了多个测试用例，用于夜间测试，进展良好。</li><li>O Stream功能已合并，Chrome标签页中的异步锁问题也已解决。</li><li>Recovery优化功能在QA环境中表现不佳，需要更多工作。</li><li>QAT功能持续更新中，有望尽快合并。</li><li>蓝鲸快照功能添加了巨大页面支持，提高了性能。</li><li>对atopic T比较器进行了优化，提高了效率。</li><li>修复了引用计数问题，简化了代码。</li><li>DW添加了列出非排序上下文的能力，提高了效率。</li></ul></li><li><p><strong>PG日志优化</strong>：</p><ul><li>Sage提出通过注释掉PG日志来优化性能的方法，但效果有限。</li><li>讨论了是否值得继续推进这一方案，并决定进行更多测试以获取更多数据。</li><li>认为在RocksDB中进行Bloom过滤器计算等额外操作是导致性能下降的主要原因。</li><li>认为需要针对不同工作负载进行测试，以确定最佳的优化方案。</li></ul></li><li><p><strong>创建PD的优化</strong>：</p><ul><li>讨论了通过创建单个PG并分割成多个副本来优化PD创建过程的方法。</li><li>认为这种方法可以减少竞争条件，提高效率。</li><li>认为Manager更适合负责这一功能，因为它不会与自动调优功能冲突。</li></ul></li><li><p><strong>蓝鲸存储内存优化</strong>：</p><ul><li>讨论了如何根据数据访问时间优先级分配内存，以提高性能。</li><li>认为可以使用时间戳或标记来区分不同优先级的缓存。</li><li>认为需要进一步测试以确定最佳的实现方案。</li></ul></li><li><p><strong>蓝鲸FS磁盘分配优化</strong>：</p><ul><li>讨论了将磁盘分配大小调整为最大值以提高性能的方法。</li><li>认为这种方法可以减少内存碎片，提高效率。</li></ul></li><li><p><strong>缓冲列表优化</strong>：</p><ul><li>讨论了将缓冲列表从链表改为向量的方法来提高性能。</li><li>认为这种方法可以减少内存碎片，提高效率。</li><li>认为需要进一步测试以确定最佳的实现方案。</li></ul></li></ol><p><strong>二、后续行动计划</strong></p><ol><li>Sage将进行更多测试，以确定PG日志优化方案的最佳实现方式。</li><li>Josh将研究创建PD的优化方案，并与John讨论具体实现方式。</li><li>Sage将研究蓝鲸存储内存优化方案的最佳实现方式。</li><li>Alex将研究蓝鲸FS磁盘分配优化方案的最佳实现方式。</li><li>Sage将研究缓冲列表优化方案的最佳实现方式。</li></ol><p><strong>三、其他事项</strong></p><ol><li>Sage请求Sage帮助解决CRC不匹配错误问题。</li><li>讨论了其他一些技术细节和问题。</li></ol>",10)])])}const P=i(r,[["render",s]]);export{u as __pageData,P as default};
